r=[]
r.append(R(6929265,"स्ट्रॉबेरी-नीबू चीज़केक","यह उलटा चीज़केक कम कैलोरी, चीनी और वसा के साथ चीज़केक के सारे स्वादों का आनंद लेने का मज़ेदार तरीका है। अगर आपको वसा रहित रिकोटा चीज़ न मिले, तो आप कॉटेज चीज़ का इस्तेमाल कर सकते हैं।","4","1/3 कप रिकोटा चीज़ + 1/2 कप स्ट्रॉबेरी",
["1 साबुत ग्राहम क्रैकर (चूरा किया हुआ)","2 कप स्ट्रॉबेरी (कटी हुई)","1/2 छोटा चम्मच पिसी दालचीनी","1 छोटा चम्मच नीबू का छिलका","3/4 छोटा चम्मच शहद","1 1/3 कप रिकोटा चीज़ (वसा रहित)"],
["एक छोटे कटोरे में रिकोटा चीज़, शहद, नीबू का छिलका और दालचीनी को मिलाएँ।","मिश्रण को चार अलग-अलग मिठाई के कटोरों में बाँट दें। हर कटोरे के ऊपर स्ट्रॉबेरी का एक हिस्सा डालें और थोड़ा ग्राहम क्रैकर का चूरा छिड़कें।"]))
r.append(R(6930473,"रोस्टेड ब्रसल्स स्प्राउट्स, चिपोटले एयोली के साथ","धुएँदार चिपोटले एयोली के साथ परोसे गए रोस्टेड ब्रसल्स स्प्राउट्स एक दमदार, मधुमेह के अनुकूल साइड डिश बनाते हैं। आसान हफ़्ते के रात के खाने के लिए इसे ग्रिल्ड चिकन ब्रेस्ट जैसे सरल कम वसा वाले प्रोटीन के साथ परोसें।","6","3/4 कप",
["1 पाउंड ब्रसल्स स्प्राउट्स (किनारे कटे और आधे कटे हुए)","2 बड़े चम्मच जैतून का तेल","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","1/2 कप लाइट मेयोनेज़","1 बड़ा चम्मच एडोबो में चिपोटले मिर्च (बारीक कटी हुई)","1 फाँक लहसुन (बारीक कटा हुआ)","1 बड़ा चम्मच नीबू का रस"],
["ओवन को 400 डिग्री F पर पहले से गरम करें।","आधे कटे ब्रसल्स स्प्राउट्स को जैतून का तेल, नमक और काली मिर्च के साथ मिलाएँ।","ब्रसल्स स्प्राउट्स को बेकिंग शीट पर एक परत में फैलाएँ।","पहले से गरम ओवन में 25 मिनट तक या ब्रसल्स स्प्राउट्स के सुनहरा भूरा और किनारों पर कुरकुरा होने तक रोस्ट करें।","जब ब्रसल्स स्प्राउट्स रोस्ट हो रहे हों, तब एयोली तैयार करें।","एक छोटे कटोरे में मेयो, बारीक कटी चिपोटले मिर्च, बारीक कटा लहसुन, नीबू का रस और नमक मिलाएँ। अच्छी तरह मिलाएँ।","ब्रसल्स स्प्राउट्स के रोस्ट हो जाने पर, उन्हें परोसने की डिश में निकालें। चिपोटले एयोली साथ में परोसें।"]))
r.append(R(6931030,"क्रीमी ग्रेवी","क्रीमी, काली मिर्च वाली ग्रेवी बिस्किट और ग्रेवी तथा चिकन फ्राइड स्टेक जैसे दक्षिणी आरामदायक भोजन का मुख्य हिस्सा है। यह मधुमेह के अनुकूल संस्करण पारंपरिक ग्रेवी में आमतौर पर मिलने वाली संतृप्त वसा को कम करने के लिए वनस्पति तेल आधारित मार्जरीन का इस्तेमाल करता है। सबसे बेहतरीन दक्षिणी आरामदायक भोजन के लिए इसे एयर फ्रायर बटरमिल्क चिकन के साथ परोसें!","4","2 बड़े चम्मच",
["1 बड़ा चम्मच मार्जरीन स्टिक","1 1/2 बड़े चम्मच मैदा (सर्व-उपयोगी आटा)","1/4 छोटा चम्मच दरदरी पिसी काली मिर्च","2/3 कप स्किम दूध"],
["एक छोटे सॉसपैन में मध्यम-तेज़ आँच पर मार्जरीन पिघलाएँ।","मैदा मिलाएँ और 1 मिनट तक लगातार चलाते हुए पकाएँ, जब तक कि मिश्रण चिकना न हो जाए। दरदरी पिसी काली मिर्च से स्वाद दें।","धीरे-धीरे स्किम दूध मिलाएँ। लगातार चलाते हुए, मिश्रण में बुलबुले उठने और उसके गाढ़ा होने तक पकाएँ।"]))
r.append(R(6931035,"आसान, बिल्कुल सही पकी मसूर दाल","अगर आपने कभी मसूर दाल नहीं पकाई है, तो इस आसान, बिल्कुल सही पकी मसूर दाल की रेसिपी के साथ इसे आज़माने का यही समय है। एक दलहन के रूप में, मसूर दाल पौधों से मिलने वाले प्रोटीन से भरपूर है और आपको संतुष्ट रखकर पूरे दिन ऊर्जावान रखेगी। हम आपको दिखाते हैं कि मसूर दाल को सेहतमंद और मधुमेह के अनुकूल तरीके से कैसे पकाएँ।\n\nस्वादिष्ट और संतोषजनक भोजन के लिए प्याज़ और शिमला मिर्च जैसी अपनी पसंदीदा बिना स्टार्च वाली सब्ज़ियाँ डालें।","4","1/2 कप",
["1 कप मसूर दाल (हरी या भूरी)","3 कप कम सोडियम वाला वेजिटेबल ब्रॉथ","1 तेज पत्ता (वैकल्पिक)"],
["महीन जाली वाली छलनी या कोलंडर में मसूर दाल को ठंडे पानी से धोएँ।","एक मध्यम सॉसपैन में धोई हुई मसूर दाल, वेजिटेबल ब्रॉथ और तेज पत्ता (अगर इस्तेमाल कर रहे हों) मिलाएँ।","मिश्रण को तेज़ आँच पर उबालें।","आँच धीमी करें, सॉसपैन को ढक्कन से ढक दें और मसूर दाल को 20–25 मिनट तक या नरम होने लेकिन अपना आकार बनाए रखने तक धीमी आँच पर पकने दें।","पक जाने पर, सॉसपैन को आँच से हटाएँ और तेज पत्ता निकाल दें।","ज़रूरत हो तो अतिरिक्त तरल निथार दें।"]))
r.append(R(6931397,"कॉटेज चीज़ और अनानास परफ़ेट","कॉटेज चीज़ और अनानास परफ़ेट की पोषण संबंधी जानकारी","1","1 कप",
["1/2 कप कम वसा वाला कॉटेज चीज़","1/2 कप अनानास (कटा हुआ)"],
["1 कप कम वसा वाला कॉटेज चीज़ कटोरे या ग्लास में चम्मच से डालें।","ऊपर 1/2 कप कटा अनानास डालें।","अगर आप मिले हुए स्वाद पसंद करते हैं तो हल्का सा चलाएँ, या परफ़ेट शैली की प्रस्तुति के लिए परतों में रहने दें।","तुरंत परोसें।"]))
r.append(R(6931629,"याया की सब्ज़ियों वाली पाएया","ज़्यादातर पाएया समुद्री भोजन या चिकन से बनती हैं, लेकिन यह शाकाहारी संस्करण भी स्वादिष्ट और प्रामाणिक है। आप चाहें तो मिश्रण में और बिना स्टार्च वाली सब्ज़ियाँ भी डाल सकते हैं!","7","लगभग 3/4 कप",
["1 बड़ा चम्मच जैतून का तेल","1 मध्यम हरी शिमला मिर्च (4 टुकड़ों में कटी हुई)","1/2 कप ताज़ी हरी फलियाँ (1/2 इंच के टुकड़ों में कटी हुई (या फ्रोज़न इस्तेमाल करें))","1 मध्यम टमाटर (छिला और कटा हुआ)","1 कप छोटे दाने वाला चावल","6 फाँक लहसुन (कुचला हुआ)","1/2 छोटा चम्मच ताज़ा अजमोदा (कटा हुआ)","1/4 छोटा चम्मच एनाटो (पिसा हुआ)","1/2 छोटा चम्मच नमक","2 कप पानी","1/2 कप फ्रोज़न लीमा बीन्स","1/2 कप आर्टिचोक हार्ट (पानी निथारे और कटे हुए)"],
["एक मध्यम फ्राइंग पैन में मध्यम आँच पर तेल गरम करें। शिमला मिर्च और हरी फलियों को 2 मिनट भूनें।","लीमा बीन्स और आर्टिचोक हार्ट को छोड़कर बाकी सामग्री डालें और उबाल आने दें। ढक दें, आँच धीमी करें और 20 मिनट धीमी आँच पर पकाएँ।","लीमा बीन्स और आर्टिचोक डालें, चलाएँ, ढक दें और 5 मिनट और पकाएँ।"]))
r.append(R(6931873,"कुरकुरे लहसुन के साथ भाप में पकी ब्रोकली","कुरकुरा लहसुन सादी भाप में पकी ब्रोकली में स्वादिष्ट आधुनिक अंदाज़ जोड़ता है। स्वादिष्ट, कम कार्बोहाइड्रेट वाली और पोषक तत्वों से भरपूर ब्रोकली उन लोगों के लिए उत्कृष्ट साइड डिश है जो रात के खाने में सेहतमंद चुनाव करने की कोशिश कर रहे हैं।","4","1 कप",
["1 पाउंड ब्रोकली (फूल)","2 बड़े चम्मच जैतून का तेल (बाँटकर)","4 फाँक लहसुन (पतला कटा हुआ)","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","2 बड़े चम्मच तिल (भुने हुए)"],
["ब्रोकली के फूलों को उबलते पानी के बरतन के ऊपर स्टीमर की टोकरी में रखें।","ब्रोकली को 5–7 मिनट या नरम-कुरकुरी होने तक भाप में पकाएँ। आँच से हटा लें।","जब ब्रोकली भाप में पक रही हो, तब एक छोटी कड़ाही में मध्यम आँच पर 1 बड़ा चम्मच जैतून का तेल गरम करें।","पतले कटे लहसुन को कड़ाही में डालें और सुनहरा भूरा और कुरकुरा होने तक 1–2 मिनट भूनें। ध्यान रखें कि लहसुन जले नहीं।","कुरकुरे लहसुन को कड़ाही से निकालें और अतिरिक्त तेल सोखने के लिए पेपर टॉवल बिछी प्लेट पर रखें।","भाप में पकी ब्रोकली को परोसने की डिश में रखें।","ब्रोकली पर 1 बड़ा चम्मच जैतून का तेल डालें और लपेटने के लिए मिलाएँ।","नमक और काली मिर्च से स्वाद दें।","भाप में पकी ब्रोकली पर कुरकुरा लहसुन और तिल छिड़कें।"]))
r.append(R(6932928,"कॉड मछली, एवोकाडो और मक्के की सालसा सलाद के साथ","कॉड एक भरपूर सफ़ेद मछली है जो अपने साथ जोड़ी गई दूसरी सामग्री का स्वाद सोख लेती है। एवोकाडो और मक्के की सालसा इस व्यंजन में ज़ायकेदार साउथवेस्टर्न स्वाद और सुंदर रंग जोड़ती है।","4","4 औंस पकी मछली + 1/2 कप सालसा",
["1 कप ग्रेप टमाटर (चार भागों में कटे हुए)","1 कप फ्रोज़न मक्का (पिघलाया हुआ)","1/4 कप हरा धनिया (कटा हुआ)","1/4 कप लाल प्याज़ (बारीक कटा हुआ)","2 बड़े चम्मच नीबू का रस","1 बड़ा चम्मच एक्स्ट्रा वर्जिन जैतून का तेल","1/2 छोटा चम्मच नमक (बाँटकर इस्तेमाल करें)","1 मध्यम एवोकाडो (पका हुआ, छिला हुआ, बीज निकाला हुआ और कटा हुआ)","4 साबुत कॉड फ़िलेट (हर एक लगभग 5 औंस, धोए और थपथपाकर सुखाए हुए)","1/2 छोटा चम्मच पिसा जीरा","1/8 छोटा चम्मच काली मिर्च"],
["कुकिंग स्प्रे लगे ग्रिल या ग्रिल पैन को मध्यम-तेज़ आँच पर पहले से गरम करें।","एवोकाडो को छोड़कर सालसा की सभी सामग्री को एक मध्यम कटोरे में मिलाएँ। एवोकाडो को धीरे से मिलाएँ और एक तरफ़ रख दें।","मछली के फ़िलेट के दोनों तरफ़ तेल लगाएँ और समान रूप से जीरा, 1/4 छोटा चम्मच नमक और काली मिर्च छिड़कें। हर तरफ़ 4 मिनट या बीच में अपारदर्शी होने तक पकाएँ। साथ में सालसा के साथ परोसें।"]))
r.append(R(6933134,"लो-कार्ब फूलगोभी ब्रेडस्टिक्स","बिना ज़्यादा कार्बोहाइड्रेट के चीज़ी लहसुन ब्रेड के स्वादिष्ट स्वाद का आनंद लें! ये \"ब्रेड\" स्टिक्स सूप या पास्ता के साथ अकेले भी बढ़िया लगती हैं। आप इस रेसिपी को लो-कार्ब पिज़्ज़ा या फ्लैटब्रेड के आधार के रूप में भी इस्तेमाल कर सकते हैं।","12","1 ब्रेडस्टिक",
["2 (16 औंस) बैग ताज़ी राइस जैसी कटी फूलगोभी","1/4 कप अंडे की सफ़ेदी","1 कप कद्दूकस किया पार्ट-स्किम मोज़ेरेला चीज़ (बाँटकर इस्तेमाल करें)","1 छोटा चम्मच लहसुन पाउडर","1 छोटा चम्मच सूखा अजवायन","1/2 छोटा चम्मच सूखी तुलसी","1/2 छोटा चम्मच सूखा थाइम","1/4 छोटा चम्मच काली मिर्च","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे"],
["अपने ओवन को 375°F पर पहले से गरम करें।","किनारे वाली बेकिंग शीट पर चर्मपत्र कागज़ (पार्चमेंट पेपर) बिछाएँ और कुकिंग स्प्रे करें। राइस जैसी कटी फूलगोभी डालें और समान परत में फैलाएँ। 15 मिनट बेक करें। फूलगोभी को ओवन से निकालें और तापमान बढ़ाकर 450°F कर दें।","एक बड़े कटोरे में पेपर टॉवल की दो परतें या साफ़ किचन टॉवल बिछाएँ। पकी फूलगोभी डालें और ठंडा होने दें।","ठंडी फूलगोभी के ऊपर टॉवल की एक और परत डालें और हाथों से दबाएँ। जितना हो सके उतना तरल निचोड़ लें।","एक बड़े मिक्सिंग बाउल में फूलगोभी, अंडे की सफ़ेदी, 1/2 कप चीज़, लहसुन पाउडर, जड़ी-बूटियाँ और काली मिर्च मिलाएँ।","अपनी बेकिंग शीट पर चर्मपत्र कागज़ (पार्चमेंट पेपर) की नई परत बिछाएँ। कुकिंग स्प्रे करें। अपने फूलगोभी के आटे को तैयार बेकिंग शीट पर रखें और लगभग 1/4” मोटे और 7x9” आकार के समान आयत में दबाएँ। 20 मिनट बेक करें, फिर ऊपर बाकी चीज़ छिड़कें। चीज़ के पिघलने और भूरा होना शुरू होने तक कुछ मिनट और ब्रॉइल करें।","ठंडा होने दें, फिर 12 ब्रेडस्टिक्स में काट लें।"]))
r.append(R(6933135,"बफ़ेलो टेम्पे \"विंग्स\"","ये शाकाहारी और लो-कार्ब बफ़ेलो टेम्पे \"विंग्स\" क्लासिक स्टार्टर का दमदार, पौधों पर आधारित विकल्प हैं, जिनमें पारंपरिक विंग्स की सारी तीखाहट और खटास है, बस संतृप्त वसा नहीं है। टेम्पे को भाप में पकाकर और बेक करके कुरकुरी बनावट मिलती है, जबकि शुगर-फ्री सॉस अतिरिक्त चीनी को काबू में रखती है। यह मज़ेदार, उच्च प्रोटीन वाला विकल्प है जो मधुमेह के प्रति सजग भोजन योजना में अच्छी तरह फिट बैठता है।","4","5 विंग्स और 1 कप सब्ज़ियाँ",
["8 औंस टेम्पे (1/4 इंच के टुकड़ों में कटा हुआ)","1 बड़ा चम्मच कम सोडियम वाला सोया सॉस","2 बड़े चम्मच सेब का सिरका","1/2 छोटा चम्मच लहसुन पाउडर","1/2 छोटा चम्मच स्मोक्ड पेपरिका","1/4 छोटा चम्मच काली मिर्च","1 बड़ा चम्मच कॉर्नस्टार्च","1/3 कप तीखी सॉस (जैसे Frank's Red Hot)","1 छोटा चम्मच शुगर-फ्री मेपल-प्रकार का सिरप (मॉन्क फ्रूट के साथ)","1 छोटा चम्मच डिजॉन सरसों","2 डंठल सेलेरी (डंडियों में कटी हुई)","2 छोटी गाजर (डंडियों में कटी हुई)","1/4 कप लाइट रैंच ड्रेसिंग (क्रीमी, कम वसा वाले दही के साथ)"],
["एक छोटे सॉसपैन में 1 इंच पानी भरें और धीमे उबाल पर लाएँ। टेम्पे को स्टीमर की टोकरी में रखें, ढक दें और नरम करने और कड़वाहट हटाने के लिए 5 मिनट भाप में पकाएँ। थपथपाकर सुखाएँ और कटोरे में डालें।","टेम्पे को सोया सॉस, 1 बड़ा चम्मच सेब का सिरका, 1/2 छोटा चम्मच लहसुन पाउडर, स्मोक्ड पेपरिका और काली मिर्च के साथ मिलाएँ। स्वाद सोखने के लिए 5 मिनट रहने दें।","ओवन को 400°F पर पहले से गरम करें और बेकिंग शीट पर चर्मपत्र कागज़ (पार्चमेंट पेपर) बिछाएँ। टेम्पे पर कॉर्नस्टार्च छिड़कें और हल्का लपेटने के लिए मिलाएँ। टेम्पे को एक परत में सजाएँ और 20 मिनट बेक करें, बीच में पलटें, जब तक कि सुनहरा और कुरकुरा न हो जाए।","एक छोटे सॉसपैन में धीमी आँच पर तीखी सॉस, 1 बड़ा चम्मच सिरका, मेपल सिरप, डिजॉन सरसों और 1/2 छोटा चम्मच लहसुन पाउडर मिलाएँ। गरम होने और अच्छी तरह मिलने तक चलाएँ।","टेम्पे को ओवन से निकालें और गरम सॉस के साथ लिपटने तक मिलाएँ। डुबोने के लिए रैंच और सेलेरी व गाजर की डंडियों के साथ परोसें।"]))
r.append(R(6933181,"शीट पैन बालसमिक चिकन और ब्रसल्स स्प्राउट्स","शीट पैन वाले रात के खाने त्वरित और आसान भोजन हैं जिनमें ज़्यादा सफ़ाई नहीं करनी पड़ती। परफ़ेक्ट और सेहतमंद हफ़्ते के रात के खाने के लिए अपने चिकन को स्वादिष्ट बालसमिक सिरके और साथ में कुरकुरे ब्रसल्स स्प्राउट्स से और बेहतर बनाएँ।","4","1 चिकन ब्रेस्ट + 1/2 कप ब्रसल्स स्प्राउट्स",
["1/4 कप बालसमिक सिरका","3 बड़े चम्मच जैतून का तेल","1 बड़ा चम्मच शहद","2 फाँक लहसुन (बारीक कटा हुआ)","1 छोटा चम्मच सूखा थाइम","1/2 छोटा चम्मच कोशर नमक","1/2 छोटा चम्मच काली मिर्च","4 साबुत बिना हड्डी और बिना त्वचा वाले चिकन ब्रेस्ट (हर एक 6 औंस)","1 बड़ा चम्मच ताज़ा अजमोदा (कटा हुआ, सजाने के लिए, वैकल्पिक)","2 छोटे चम्मच नीबू का छिलका (सजाने के लिए, वैकल्पिक)"],
["ओवन को 400 डिग्री F पर पहले से गरम करें। एक बड़ी बेकिंग शीट पर चर्मपत्र कागज़ (पार्चमेंट पेपर) बिछाएँ।","एक छोटे कटोरे में मैरिनेड बनाने के लिए बालसमिक सिरका, जैतून का तेल, शहद, बारीक कटा लहसुन, सूखा थाइम, कोशर नमक और काली मिर्च को फेंटें।","चिकन ब्रेस्ट को एक बड़े कटोरे में रखें और मैरिनेड को चिकन पर डालें, यह सुनिश्चित करते हुए कि वह अच्छी तरह लिपट जाए।","चिकन ब्रेस्ट को शीट पैन पर सजाएँ और ब्रसल्स स्प्राउट्स को दूसरे पर रखें।","ब्रसल्स स्प्राउट्स को उसी कटोरे में डालें और बचे हुए मैरिनेड से अच्छी तरह लपेटें। ब्रसल्स स्प्राउट्स को शीट पैन पर चिकन के चारों ओर सजाएँ।","पहले से गरम ओवन में तब तक बेक करें जब तक चिकन का आंतरिक तापमान 165 डिग्री F न हो जाए, लगभग 25–30 मिनट।","ओवन से निकालें, कुछ मिनट रहने दें, और फिर, अगर इस्तेमाल कर रहे हों तो, ताज़े अजमोदा और नीबू के छिलके और रस से सजाएँ।"]))
r.append(R(6934057,"बेकन के साथ रोस्टेड ब्रसल्स स्प्राउट्स","इस सरल, लो-कार्ब साइड डिश को अपने पसंदीदा प्रोटीन वाले मुख्य व्यंजन में शामिल करें। रोस्ट करने से ब्रसल्स स्प्राउट्स का स्वाद बढ़ जाता है, और टर्की बेकन स्वादिष्ट नमकीनपन और ज़ायका जोड़ता है। यहाँ आप ताज़े या फ्रोज़न ब्रसल्स स्प्राउट्स इस्तेमाल कर सकते हैं।","5","6 ब्रसल्स स्प्राउट्स (लगभग 1/2 कप)",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1 पाउंड फ्रोज़न ब्रसल्स स्प्राउट्स (पिघलाए हुए)","2 बड़े चम्मच जैतून का तेल","1/2 छोटा चम्मच काली मिर्च","3 स्लाइस टर्की बेकन (एक्स्ट्रा लीन, 1 इंच के टुकड़ों में कटा हुआ)"],
["ओवन को 400 डिग्री F पर पहले से गरम करें। बेकिंग शीट पर कुकिंग स्प्रे करें।","ब्रसल्स स्प्राउट्स को कटोरे में रखें और तेल डालें; लपेटने के लिए मिलाएँ।","बाकी सामग्री डालें और अच्छी तरह मिलाएँ।","ब्रसल्स स्प्राउट्स को बेकिंग शीट पर रखें और 35-40 मिनट या बाहर से कुरकुरे होने तक बेक करें।"]))
r.append(R(6935097,"सब्ज़ियों वाला वैफ़ल ऑमलेट","यह रचनात्मक वैफ़ल ऑमलेट अंडे की सफ़ेदी, रंगीन सब्ज़ियों और कम वसा वाले टर्की सॉसेज को मिलाकर एक मज़ेदार, प्रोटीन से भरपूर नाश्ता बनाता है जिसमें कार्बोहाइड्रेट नहीं है। इसे वैफ़ल आयरन में पकाने से अतिरिक्त तेल या आटे के बिना कुरकुरे किनारे मिलते हैं। कम संतृप्त वसा और उच्च प्रोटीन मात्रा के साथ, यह अपने दिन की संतोषजनक शुरुआत चाहने वाले मधुमेह वाले लोगों के लिए बढ़िया विकल्प है। यह लो-कार्ब, बहुत कम कार्बोहाइड्रेट और कम वसा वाली रेसिपी है।","1","1 वैफ़ल ऑमलेट",
["12 औंस अंडे की सफ़ेदी","1/2 कप चेडर चीज़ (कम वसा वाला, कद्दूकस किया हुआ)","1/2 कप टर्की सॉसेज (कटा हुआ, पका हुआ [कम सोडियम वाली किस्म चुनें])","1/2 कप शिमला मिर्च (कटी हुई)","1/2 कप प्याज़ (कटा हुआ)","1/8 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च (पिसी हुई)","1 साबुत नॉनस्टिक कुकिंग स्प्रे","1 बड़ा चम्मच ताज़ा चाइव्स (कटे हुए)"],
["अपने वैफ़ल आयरन को कम या मध्यम सेटिंग पर सेट करें और पहले से गरम होने दें। ऊपरी और निचली दोनों प्लेटों पर हल्का सा कुकिंग स्प्रे लगाएँ।","अंडे की सफ़ेदी को एक बड़े कटोरे में रखें। हल्का झागदार होने तक ज़ोर से फेंटें।","अंडों में कद्दूकस किया चीज़, कटा टर्की सॉसेज, शिमला मिर्च, प्याज़ और काली मिर्च डालें। सभी सामग्री के समान रूप से मिलने तक चलाएँ।","अंडे के मिश्रण का एक हिस्सा पहले से गरम वैफ़ल आयरन के बीच में डालें, ध्यान रखें कि ज़्यादा न भरे। ढक्कन को धीरे से बंद करें। लगभग 3-5 मिनट तक या अंडे के पूरी तरह जमने और सतह के हल्का सुनहरा होने तक पकाएँ। पकाने का समय आपके वैफ़ल आयरन के अनुसार अलग हो सकता है; ज़्यादा पकने से बचाने के लिए ध्यान से देखते रहें।","स्पैचुला की मदद से ऑमलेट को वैफ़ल आयरन से सावधानी से निकालें। बचे हुए अंडे के मिश्रण के साथ यही प्रक्रिया दोहराएँ। चाइव्स से सजाकर गरमागरम परोसें।"]))
r.append(R(6935912,"टोफू स्प्रिंग रोल्स","आप इस रेसिपी को और भी कम कार्बोहाइड्रेट वाला बनाने के लिए राइस पेपर की जगह सिर्फ़ लेट्यूस को रैपर बनाकर भी ये स्प्रिंग रोल्स बना सकते हैं।","6","1 स्प्रिंग रोल",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1 बड़ा चम्मच कम सोडियम वाला सोया सॉस","1 छोटा चम्मच कम कैलोरी वाला ब्राउन शुगर विकल्प","12 औंस एक्स्ट्रा फ़र्म टोफू","6 साबुत स्प्रिंग रोल रैपर (राइस पेपर, हर एक 0.25 औंस)","2 कप गुनगुना पानी","6 पत्ते लेट्यूस के पत्ते","1 मध्यम आम (छिला और पतला कटा हुआ)","1 छोटा खीरा (छिला, बीज निकाला और पतली पट्टियों में कटा हुआ)","1/2 मध्यम एवोकाडो (12 पतले टुकड़ों में कटा हुआ)","1/2 कप बिना चीनी मिलाए खुबानी का जैम","1 बड़ा चम्मच सोया सॉस (कम सोडियम वाला, सॉस के लिए)","1/2 छोटा चम्मच थाई शैली की चिली गार्लिक सॉस (सॉस के लिए)"],
["ओवन को 475 डिग्री F पर पहले से गरम करें। बेकिंग शीट पर कुकिंग स्प्रे लगाकर एक तरफ़ रख दें।","एक छोटे कटोरे में सोया सॉस और ब्राउन शुगर विकल्प को फेंटें।","टोफू को 6 टुकड़ों में काटें। बेकिंग शीट पर रखें और हर टुकड़े पर सोया सॉस का मिश्रण हल्का सा लगाएँ। 20 मिनट बेक करें। पूरी तरह ठंडा होने दें।","टोफू के ठंडा होने पर, हर टुकड़े को तीन छोटे टुकड़ों में काट लें।","आम और खीरे को 6-6 बराबर हिस्सों में बाँटें।","एक राइस पेपर रैपर को गुनगुने पानी में नरम होने तक, लगभग 30 सेकंड, भिगोएँ। राइस पेपर को साफ़, समतल सतह पर बिछाएँ। राइस पेपर के ऊपर एक लेट्यूस का पत्ता रखें।","राइस पेपर के बीच में आम और खीरे का एक-एक हिस्सा रखें। सब्ज़ियों के ऊपर टोफू के 3 छोटे टुकड़े और एवोकाडो के दो टुकड़े रखें।","रैपर और लेट्यूस के बाएँ और दाएँ किनारे बीच में लगभग छूने तक मोड़ें। नीचे से पेपर को कसकर रोल बनाते हुए लपेटें। बाकी राइस पेपर के साथ दोहराएँ। एक तरफ़ रख दें।","सॉस की सामग्री को एक छोटे सॉसपैन में तेज़ आँच पर मिलाएँ। लगातार चलाते हुए उबाल आने दें। 2 मिनट धीमी आँच पर पकाएँ। डुबोने के लिए ठंडे स्प्रिंग रोल्स के साथ गरम परोसें।"]))
r.append(R(6937788,"हरी शिमला मिर्च एन्चिलाडास","एक पसंदीदा मैक्सिकन व्यंजन के स्वादिष्ट अंदाज़ - हरी शिमला मिर्च एन्चिलाडास - से अपने भोजन के समय में मसाला जोड़ें! चाहे आप टेक्स-मेक्स व्यंजनों के शौकीन हों या अपनी रात के खाने की मेज़ पर कुछ रोमांच जोड़ना चाहते हों, ये एन्चिलाडास मधुमेह के अनुकूल आनंद हैं।\n\nशेफ़ की सलाह: इन्हें पहले से बनाकर बाद में त्वरित भोजन के लिए फ्रीज़ किया जा सकता है।","4","2 एन्चिलाडास",
["1 मध्यम हरी शिमला मिर्च (कटी हुई)","1 मध्यम हलापेन्यो मिर्च (बारीक कटी हुई)","1 डंठल हरा प्याज़ (स्प्रिंग ओनियन) (कटा हुआ)","3 फाँक लहसुन (बारीक कटा हुआ)","2 कप पका हुआ चिकन (रेशे किया हुआ)","3 बड़े चम्मच जैतून का तेल","3 बड़े चम्मच मैदा (सर्व-उपयोगी आटा)","2 कप कम सोडियम वाला चिकन ब्रॉथ","1/4 छोटा चम्मच कोशर नमक","1/2 छोटा चम्मच पिसा धनिया","1/2 कप सादा वसा रहित ग्रीक दही","1/4 कप कद्दूकस किया मैक्सिकन चीज़ मिश्रण (कम वसा वाला)","8 छोटी मक्के की टॉर्टिला (6 इंच)"],
["ओवन को 350°F पर पहले से गरम करें।","एक बड़ी कड़ाही पर कुकिंग स्प्रे करें और मध्यम आँच पर गरम करें। हरी शिमला मिर्च, हलापेन्यो, हरा प्याज़ और लहसुन डालें। मध्यम आँच पर 4–5 मिनट पकाएँ, जब तक कि शिमला मिर्च नरम होना शुरू न हो जाए।","आँच से हटाएँ और रेशे किए हुए चिकन के साथ कटोरे में रखकर मिलाएँ। एक तरफ़ रख दें।","कड़ाही को वापस आँच पर रखें और जैतून का तेल डालें। चिकना होने तक लगभग 1 मिनट मैदा फेंटकर मिलाएँ।","धीरे-धीरे चिकन ब्रॉथ डालें, फेंटते हुए जब तक सॉस गाढ़ी और चिकनी न हो जाए, लगभग 3–4 मिनट। नमक, धनिया और दही डालें और चिकना होने तक फेंटें। आँच से हटा लें।","10 x 8 (या मध्यम आकार की) बेकिंग डिश में थोड़ी सी सॉस डालें। तली को ढकने के लिए फैलाएँ।","टॉर्टिला को समतल सतह पर रखें और चिकन और शिमला मिर्च के मिश्रण को उनमें बाँटें, मिश्रण को हर एक के बीच में रखते हुए। कसकर लपेटें और जोड़ वाली तरफ़ नीचे करके बेकिंग डिश में रखें। बची हुई सॉस भरी हुई टॉर्टिला पर डालें और ऊपर से कद्दूकस किया चीज़ छिड़कें।","15–20 मिनट बेक करें, जब तक सॉस में बुलबुले न उठने लगें और चीज़ पिघल न जाए।"]))
save(6,r)
